/**
 * Die Höhlen als Graph mit Adjazenzmatrix (wie in Klasse 11).
 * Suche (Strg + F) nach "TODO".
 */
public class Graph {
   Knoten[] knoten;     // knoten[i] ist die Höhle mit der Nummer i
   boolean[][] adja;    // adja[start][ende] ist true, wenn es einen Gang gibt
   int maxAnzahl = 20;
   int anzKnoten = 10;

   Graph() {
      knoten = new Knoten[maxAnzahl];
      adja = new boolean[maxAnzahl][maxAnzahl];
      int[] x = {90, 500, 360, 300, 450, 560, 110, 640, 270, 710};
      int[] y = {90, 230, 420, 250, 60, 430, 330, 90, 70, 520};
      String buchstaben = "TEGSIHACLT";
      for (int i = 0; i < anzKnoten; i++) {
         knoten[i] = new Knoten(x[i], y[i], i, "" + buchstaben.charAt(i));
      }
      kanteHinzufuegen(0, 6);
      kanteHinzufuegen(0, 8);
      kanteHinzufuegen(1, 2);
      kanteHinzufuegen(1, 3);
      kanteHinzufuegen(2, 5);
      kanteHinzufuegen(2, 6);
      kanteHinzufuegen(3, 6);
      kanteHinzufuegen(3, 8);
      kanteHinzufuegen(4, 7);
      kanteHinzufuegen(4, 8);
      kanteHinzufuegen(5, 9);
   }

   /**
    * Startet die Tiefensuche (fertig): legt das Gedächtnis an und ruft die Rekursion auf.
    */
   void tiefensuche(int startKnoten, int zielKnoten) {
      boolean[] besucht = new boolean[anzKnoten];
      for (int i = 0; i < anzKnoten; i++) {
         knoten[i].setFillColor(Color.gray);
      }
      print("Buchstaben auf dem Weg: ");
      boolean gefunden = tiefensucheRekursiv(startKnoten, zielKnoten, besucht);
      println("");
      if (gefunden) {
         println("Ausgang gefunden!");
      } else {
         println("Kein Weg zum Ausgang gefunden.");
      }
   }

   /**
    * Die rekursive Tiefensuche. Rückgabe true, sobald das Ziel erreicht ist.
    * Die Schritte ① bis ⑥ stehen auf dem Blatt und im Code-Schloss (Raum 5).
    */
   boolean tiefensucheRekursiv(int aktuellerKnoten, int zielKnoten, boolean[] besucht) {
      // TODO 1 (Finale): ① Höhle als besucht markieren
      knoten[aktuellerKnoten].betreten();          // färbt die Höhle grün und gibt ihren Buchstaben aus

      // TODO 2: ② Ziel erreicht? Dann true zurückgeben

      // TODO 3: ③ alle Höhlen i durchgehen,
      //         ④ ist i ein Nachbar und noch nicht besucht,
      //         ⑤ dort weitersuchen – und true weitergeben, wenn das Ziel gefunden wurde

      return false;                                // ⑥ Sackgasse: zurück
   }

   /**
    * Breitensuche aus Klasse 11 (fertig, zum Vergleich in Raum 6).
    */
   void breitensuche(int startKnoten, int zielKnoten) {
      LinkedList<Integer> besuchteKnoten = new LinkedList<Integer>();
      LinkedList<Integer> warteschlange = new LinkedList<Integer>();
      for (int i = 0; i < anzKnoten; i++) {
         knoten[i].setFillColor(Color.gray);
      }
      print("Buchstaben auf dem Weg: ");
      int aktuellerKnoten = startKnoten;
      warteschlange.add(aktuellerKnoten);
      while (aktuellerKnoten != zielKnoten && !warteschlange.isEmpty()) {
         aktuellerKnoten = warteschlange.poll();
         besuchteKnoten.add(aktuellerKnoten);
         knoten[aktuellerKnoten].betreten();
         for (int i = 0; i < anzKnoten; i++) {
            if (adja[aktuellerKnoten][i] && !besuchteKnoten.contains(i) && !warteschlange.contains(i)) {
               warteschlange.addLast(i);
            }
         }
      }
      println("");
   }

   // ----- fertige Methoden wie in Klasse 11, müssen nicht verändert werden -----

   // Fügt einen ungerichteten Gang zwischen start und ende hinzu.
   void kanteHinzufuegen(int start, int ende) {
      adja[start][ende] = true;
      adja[ende][start] = true;
      zeichneKante(start, ende);
   }

   // Gibt die Adjazenzmatrix mit X (Gang) und O (kein Gang) aus.
   void printAdja() {
      for (int zeile = 0; zeile < anzKnoten; zeile++) {
         for (int spalte = 0; spalte < anzKnoten; spalte++) {
            if (adja[zeile][spalte]) {
               print("X ");
            } else {
               print("O ");
            }
         }
         println("");
      }
   }

   // Zeichnet einen Gang als halbtransparenten Balken.
   void zeichneKante(int start, int ende) {
      double startX = knoten[start].getCenterX();
      double startY = knoten[start].getCenterY();
      double endeX = knoten[ende].getCenterX();
      double endeY = knoten[ende].getCenterY();
      double abstand = Vector2.distance(startX, startY, endeX, endeY);
      double winkel = new Vector2(endeX - startX, endeY - startY).getAngleDeg();
      Rectangle balken = new Rectangle(startX, startY, 10, abstand);
      balken.setFillColor(Color.white);
      balken.setAlpha(0.5);
      balken.rotate(90 - winkel, startX, startY);
      knoten[start].bringeNachVorne();
      knoten[ende].bringeNachVorne();
   }
}

/**
 * Eine Höhle: ein Kreis mit Nummer und einem Buchstaben an der Wand.
 * Fertig, muss nicht verändert werden.
 */
class Knoten extends Circle {
   private String knotenname;
   private String buchstabe;
   private Text beschriftung;

   Knoten(double x, double y, int nummer, String buchstabe) {
      super(x, y, 32);
      this.knotenname = "" + nummer;
      this.buchstabe = buchstabe;
      setFillColor(Color.gray);
      setBorderColor(Color.white);
      beschriftung = new Text(x, y - 14, 24, knotenname);
      beschriftung.setAlignment(Alignment.center);
      beschriftung.setFillColor(Color.white);
   }

   String getKnotenname() {
      return knotenname;
   }

   // Die Suche betritt die Höhle: grün färben, Buchstaben zeigen und ausgeben
   void betreten() {
      setFillColor(Color.green);
      beschriftung.setText(knotenname + ":" + buchstabe);
      print(buchstabe);
   }

   void bringeNachVorne() {
      bringToFront();
      beschriftung.bringToFront();
   }
}
